-- 虚拟演示班（示例专业2605班（演示））全套数据
-- 生成器：scripts/gen-demo-class.js（改数据请改生成器，不要手改本文件）
-- 执行：bash scripts/run_sql_file.sh scripts/demo-class.sql
-- 回滚：bash scripts/run_sql_file.sh scripts/demo-class-rollback.sql
-- 成员 40 人 / 课程 9 门 / 课次 21 个 / 值日 294 条
-- ===== 0. 清理旧的演示班（重复执行安全） =====;
DELETE FROM duty WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM session WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM course WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM duty_slot WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM schedule_rules WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM duty_week_cursor WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM notice_msg_read WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM notice_msg_target WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM notice_msg_class WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM notice_msg WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM class_fund_record WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM class_fund WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM member WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
DELETE FROM `class` WHERE invite_code = 'DEMO2605';
-- ===== 1. 虚拟班级 =====;
-- ===== 2. 40 名虚构成员（学号 000000000501–40） =====;
-- ===== 3. 9 门课程（教师姓名全虚构，含保洁宿主课） =====;
-- ===== 4. 课次：16 个课程课次 + 5 个保洁课次（18:10 打扫 412） =====;
-- ===== 5. 值日岗位：每工作日 5 个课程岗 + 1 个保洁岗 =====;
-- ===== 6. 排班规则 + 轮转游标 =====;
-- ===== 7. 值日轮转：1–7 周，共 294 条 =====;
-- ===== 8. 三条通知（其中两条需要确认收到） =====;
-- ===== 9. 班费：总额 280，两笔支出 6.1，余额 273.9 =====;
-- ===== 10. 回写 member.duty_count（值日页的完成数口径） =====;
UPDATE member SET duty_count = (SELECT COUNT(*) FROM duty d WHERE d.member_id = member.id AND d.status = 'DONE') WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
-- ===== 11. 自检（执行后看这几行输出） =====;
SELECT id, name, invite_code, join_token, term_start, total_weeks, main_room FROM `class` WHERE invite_code = 'DEMO2605';
SELECT COUNT(*) AS members, SUM(group_tag = 'A') AS grp_a, SUM(group_tag = 'B') AS grp_b FROM member WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
SELECT (SELECT COUNT(*) FROM course WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1)) AS courses, (SELECT COUNT(*) FROM session WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1)) AS sessions, (SELECT COUNT(*) FROM duty WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1)) AS duties, (SELECT COUNT(*) FROM duty_slot WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1)) AS slots;
SELECT status, COUNT(*) AS n FROM duty WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1) GROUP BY status;
SELECT MIN(class_date) AS first_date, MAX(class_date) AS last_date FROM duty WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1);
SELECT SUM(amount) AS expense, (SELECT total FROM class_fund WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1) AND type = 'class') - SUM(amount) AS balance FROM class_fund_record WHERE class_id = (SELECT id FROM `class` WHERE invite_code = 'DEMO2605' LIMIT 1) AND type = 'class';
